using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpStdioServer;

public class ApiTools(IHttpClientFactory httpClientFactory)
{
    [McpServerTool(Name = "fetch_post"), Description("Fetches a post by ID from the external API.")]
    public async Task<string> FetchPost(
        [Description("The numeric ID of the post to fetch.")] int postId,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"/posts/{postId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return json.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpStdioServer;

public static class SummarizePrompts
{
    [McpServerPrompt(Name = "summarize"), Description("Creates a prompt to summarize the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Optional maximum length for the summary (e.g. '2 sentences').")] string? maxLength = null)
    {
        var instruction = maxLength is not null
            ? $"Summarize the following text in at most {maxLength}."
            : "Summarize the following text concisely.";

        return
        [
            new()
            {
                Role = Role.User,
                Content = new TextContentBlock($"{instruction}\n\n{text}")
            }
        ];
    }
}

